[https://github.com/miloyip/rapidjson/blob/master/include/rapidjson/document.h](url) line 2296
```c++
template <unsigned parseFlags, typename SourceEncoding>
    GenericDocument& Parse(const typename SourceEncoding::Ch* str, size_t length) {
        RAPIDJSON_ASSERT(!(parseFlags & kParseInsituFlag));
        MemoryStream ms(static_cast<const char*>(str), length * sizeof(typename SourceEncoding::Ch));
        EncodedInputStream<SourceEncoding, MemoryStream> is(ms);
        ParseStream<parseFlags, SourceEncoding>(is);
        return *this;
}
```
The follow code snippet causes a compilation error: 
error C2440: 'static_cast' : cannot convert from 'const wchar_t *' to 'const char *'
```c++
void foo()
{
	std::wstring_view s = L"{}";
	rapidjson::GenericDocument<rapidjson::UTF16<>> json;
	json.Parse(s.data(), s.length());
}
```
Maybe there should be reinterpret_cast.
